import discordfrom discord import Colorfrom discord.ext import commandsfrom utils.EmbedGeneratorUtil import EmbedGeneratorclass PingCommand(commands.Cog):    def __init__(self, bot: commands.Bot):        self.bot = bot    @commands.command(name="ping", help="Simple command to test bot uptime and connectivity")    async def ping(self, ctx: discord.ext.commands.Context):        """        Simple command to test bot uptime and connectivity.        :param ctx: This is the discord Interaction we can access data from.        :return:        """        embed = EmbedGenerator(self.bot).generate_simple_message_embed(description="Pong!", colour=Color.dark_blue(), timestamp=False)        await ctx.reply(embed=embed, mention_author=False)async def setup(bot: commands.Bot):    await bot.add_cog(PingCommand(bot))